<div class="toolbar"><div class="container-fluid"><h1 class="fs-3 fw-bold mb-1">Complaint Types</h1><div class="text-muted">Manage complaint types used for employee grievances.</div></div></div><div class="container-fluid py-6">@foreach(['success'=>'success','error'=>'error'] as $key=>$icon)@if(session($key))<script>Swal.fire({icon:'{{$icon}}',text:@json(session($key))})</script>@endif @endforeach<div class="ct-grid"><div class="card ct-card"><form id="ctForm" method="POST" action="{{route('complaint-types-store')}}" novalidate>@csrf<span id="ctMethod"></span><div class="card-header pt-6"><h3 id="ctTitle">Add New Complaint Type</h3></div><div class="card-body"><div class="mb-5"><label class="form-label required">Type Name</label><input class="form-control" name="name" placeholder="e.g. Harassment, Discrimination"></div><div class="mb-5"><label class="form-label">Description</label><textarea class="form-control" rows="4" name="description" placeholder="Brief description"></textarea></div><div class="mb-5"><label class="form-label required">Status</label><select class="form-select" name="status"><option value="1">Active</option><option value="0">Inactive</option></select></div><button class="btn btn-success" id="ctSave">Add Complaint Type</button><button type="button" class="btn btn-light" id="ctCancel" style="display:none" onclick="resetCT()">Cancel</button></div></form></div><div><div class="card ct-card mb-5"><form class="card-body d-flex gap-3"><input class="form-control" name="search" value="{{request('search')}}" placeholder="Search complaint types..."><button class="btn btn-success">Search</button>@if(request('search'))<a class="btn btn-light-danger" href="{{route('complaint-types-index')}}">Clear</a>@endif</form></div><div class="card ct-card overflow-hidden"><div class="ct-row fw-bold bg-light"><span>Name</span><span>Status</span><span class="text-center">Actions</span></div>@forelse($types as $t)<div class="ct-row"><div><strong>{{$t->name}}</strong><div class="text-muted">{{$t->description?:'—'}}</div></div><span><span class="badge badge-light-{{$t->status?'success':'danger'}}">{{$t->status?'Active':'Inactive'}}</span></span><div class="ct-actions d-flex justify-content-center gap-3"><button data-item="{{base64_encode(json_encode($t))}}" onclick="editCT(this.dataset.item)" title="Edit"><svg viewBox="0 0 24 24"><path d="M12 20H5a1 1 0 0 1-1-1v-7"/><path d="m16.5 3.5 4 4L11 17l-5 1 1-5Z"/></svg></button><form method="POST" action="{{route('complaint-types-toggle',$t)}}">@csrf @method('PATCH')<button title="Change status"><svg viewBox="0 0 24 24"><path d="M20 11a8 8 0 1 0-2.3 5.7"/><path d="M20 4v7h-7"/></svg></button></form><form method="POST" action="{{route('complaint-types-destroy',$t)}}" class="ct-delete">@csrf @method('DELETE')<button title="Delete"><svg viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m5 4v7m4-7v7"/></svg></button></form></div></div>@empty<div class="p-8 text-center text-muted">No complaint types found.</div>@endforelse<div class="p-4">{{$types->links('pagination::bootstrap-4')}}</div></div></div></div></div>
<script>const cs=@json(route('complaint-types-store')),cu=@json(route('complaint-types-update','__ID__'));function editCT(x){let d=JSON.parse(atob(x)),f=ctForm;f.action=cu.replace('__ID__',d.id);ctMethod.innerHTML='<input type="hidden" name="_method" value="PUT">';f.elements.name.value=d.name;f.elements.description.value=d.description||'';f.elements.status.value=d.status?1:0;ctTitle.textContent='Edit Complaint Type';ctSave.textContent='Update Complaint Type';ctCancel.style.display='inline-block'}function resetCT(){ctForm.reset();ctForm.action=cs;ctMethod.innerHTML='';ctTitle.textContent='Add New Complaint Type';ctSave.textContent='Add Complaint Type';ctCancel.style.display='none'}document.addEventListener('DOMContentLoaded',()=>{ctForm.onsubmit=e=>{if(!ctForm.elements.name.value.trim()){e.preventDefault();Swal.fire({icon:'error',text:'Type Name is required'})}};document.querySelectorAll('.ct-delete').forEach(f=>f.onsubmit=e=>{if(f.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete complaint type?',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f1416c'}).then(r=>{if(r.isConfirmed){f.dataset.ok=1;f.submit()}})})})</script>
